$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot
$rows=@(Get-Content (Join-Path $root 'docs/lab8-results/summary.json') -Raw|ConvertFrom-Json)
$lines=@('# Lab 8 — Resilience Engineering','',"Дата прогону: $(Get-Date -Format 'yyyy-MM-dd HH:mm'). Контрольний режим: $($rows[0].vus) VUs; тривалість $($rows[0].seconds) с на сценарій. DB loads — контрольні лічильники SQL-завантажень PostgreSQL, збережені у Redis.",'','| Режим | VUs | RPS | p95 ms | p99 ms | HTTP errors % | Failed checks | Resource DB loads | Missing entity DB loads | Avalanche DB loads |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|')
foreach($r in $rows){$lines+="| $($r.mode) | $($r.vus) | $($r.rps) | $($r.p95Ms) | $($r.p99Ms) | $($r.errorPct) | $($r.failedChecks) | $($r.resourceDbLoads) | $($r.entityDbLoads) | $($r.avalancheDbLoads) |"}
$unprotected=@($rows|Where-Object mode -eq 'unprotected')[0];$protected=@($rows|Where-Object mode -eq 'protected')[0]
$sync=@($rows|Where-Object mode -eq 'avalanche-sync')[0];$jitter=@($rows|Where-Object mode -eq 'avalanche-jitter')[0]
$lines+=@('','## Analysis','',"При одночасному MISS режим unprotected допускає паралельні завантаження. Protected використовує Redis SET NX lock з випадковим token, повторне читання кешу та compare-and-delete під час звільнення блокування. Порівняння за цим запуском: resource DB loads $($unprotected.resourceDbLoads) → $($protected.resourceDbLoads); RPS $($unprotected.rps) → $($protected.rps); p99 $($unprotected.p99Ms) → $($protected.p99Ms) ms.",'',"Avalanche: синхронний TTL спричинив $($sync.avalancheDbLoads) контрольних завантажень джерела, TTL jitter — $($jitter.avalancheDbLoads). Порівнюйте ці числа за однакового VU, тривалості й стану кешу.",'','Negative caching зберігає маркер відсутності 15 секунд. TTL основного ресурсу має базу 30 секунд і рівномірний jitter ±10 секунд; endpoint повертає фактичний TTL у `X-Cache-TTL-Seconds`.')
$lines+=@('','## Failure modes та компроміси','','- Redis недоступний: блокування недоступне, сервіс переходить до БД без координації; це може спричинити herd.','- Lock має TTL 15 секунд; якщо обчислення триває довше, інший вузол може отримати lock. Для довгих задач треба продовження lease/fencing token.','- Очікування coalesced запиту обмежене 2 секундами; після timeout запит може піти до БД.','- Negative cache на 15 секунд затримує появу щойно створеної сутності; запис має інвалідовувати відповідний negative key у production.','- TTL jitter зменшує синхронне expiration, але не прибирає stampede для одного надзвичайно популярного ключа.','- Лічильники підтверджують спроби SQL-завантаження у контрольних endpoint-ах; production потребує моніторингу PostgreSQL і Redis.','', '## Обмеження','','Порівнюйте режими на однаковій машині та однаковій тривалості. Smoke є лише перевіркою й може не дочекатися TTL expiry. Для порівняння 500 VUs запустіть `pwsh -NoProfile -File load-tests/run-lab8.ps1 -StageSeconds 30`.')
$svgPath=Join-Path $root 'docs/lab8-results/latency-chart.svg'
$chartRows=@($rows)
$chartMax=[math]::Max(1,(@($chartRows|ForEach-Object{[double]$_.p99Ms}|Measure-Object -Maximum).Maximum))
$svg=[Collections.Generic.List[string]]::new();$svg.Add('<svg xmlns="http://www.w3.org/2000/svg" width="900" height="360" viewBox="0 0 900 360">');$svg.Add('<rect width="900" height="360" fill="white"/><text x="450" y="28" text-anchor="middle" font-family="Arial" font-size="20">Lab 8 latency by scenario</text>')
$svg.Add('<line x1="70" y1="300" x2="870" y2="300" stroke="#555"/><text x="18" y="175" transform="rotate(-90 18 175)" font-family="Arial" font-size="13">Latency (ms)</text>')
$slot=780/[math]::Max(1,$chartRows.Count)
for($i=0;$i -lt $chartRows.Count;$i++){ $row=$chartRows[$i];$center=90+$i*$slot+$slot/2;$p95=[double]$row.p95Ms;$p99=[double]$row.p99Ms;$h95=250*$p95/$chartMax;$h99=250*$p99/$chartMax;$x=[int]($center-22);$svg.Add("<rect x='$x' y='$([int](300-$h95))' width='20' height='$([int]$h95)' fill='#3478c8'/><rect x='$($x+22)' y='$([int](300-$h99))' width='20' height='$([int]$h99)' fill='#ed8b32'/><text x='$center' y='322' text-anchor='middle' font-family='Arial' font-size='11'>$($row.mode)</text><text x='$([int]($center-12))' y='$([int](294-$h95))' text-anchor='middle' font-family='Arial' font-size='9'>$p95</text><text x='$([int]($center+32))' y='$([int](294-$h99))' text-anchor='middle' font-family='Arial' font-size='9'>$p99</text>") }
$svg.Add('<rect x="680" y="42" width="12" height="12" fill="#3478c8"/><text x="698" y="53" font-family="Arial" font-size="12">p95</text><rect x="744" y="42" width="12" height="12" fill="#ed8b32"/><text x="762" y="53" font-family="Arial" font-size="12">p99</text></svg>')
$svg|Set-Content $svgPath -Encoding utf8
$lines+=@('','## Latency graph','','![p95 and p99 latency by scenario](latency-chart.svg)')
$lines|Set-Content (Join-Path $root 'docs/lab8-results/report.md') -Encoding utf8
